class CashOperatingOutflowControl(Factor):
    def calculate(self, factors):
        close = factors['close'].astype('float64')
        cash = factors['cash_flow_from_operating_activities'].astype('float64')
        outflow = factors['cash_paid_for_operation_activities'].astype('float64')
        value = (cash/outflow).reindex(close.index)
        valid = (outflow > 0).reindex(close.index, fill_value=False)
        return value.where(valid & ((value-value) == 0) & (close > 0)).rename('value')
